example.code:
public class MyAddNode : ResultNode<float>
{
    public MyAddNode(NodeContext ctx, ShaderNode<float> a, ShaderNode<float> b)
        : base(ctx, "MyAdd")
    {
        SetInputs(new AbstractShaderNode[] { a, b });
    }

    protected override string ImplementationTemplate() => "${a} + ${b}";
}

public class Multiply<T> : ResultNode<T> where T : struct
{
    public Multiply(NodeContext ctx, ShaderNode<T> a, ShaderNode<T> b)
        : base(ctx, "Multiply")
    {
        SetInputs(new AbstractShaderNode[] { a, b });
    }

    protected override string ImplementationTemplate() => "${a} * ${b}";
}
